# Apartats 6.1-6.5 (raons i proporcions, proporcionalitat directa, inversa i composta, repartiments) dels apunts de la
# Unitat 6 de 2n ESO. Les asserts ck() comproven els resultats escrits a mà.
from comu import *

def frow(*cells): return '<span class="frin">' + ''.join(cells) + '</span>'
def bare(k, val, mode='decimal'): return nin(k, '', '', '', val, 's', mode).replace('<label>', '').replace('</label>', '')
DIES = r'\tri{dies}{días}{days}'

# ============================================================ 6.1
s1 = box('def', L('Raó entre dos nombres', 'Razón entre dos números', 'Ratio of two numbers'),
  P(r"La <strong>raó</strong> entre dos nombres \(a\) i \(b\) és el quocient \(\dfrac{a}{b}\), que es llig «\(a\) és a \(b\)». Serveix per a <strong>comparar</strong> dues quantitats.",
    r"La <strong>razón</strong> entre dos números \(a\) y \(b\) es el cociente \(\dfrac{a}{b}\), que se lee «\(a\) es a \(b\)». Sirve para <strong>comparar</strong> dos cantidades.",
    r"The <strong>ratio</strong> of two numbers \(a\) and \(b\) is the quotient \(\dfrac{a}{b}\), read “\(a\) is to \(b\)” (also written \(a:b\)). It's used to <strong>compare</strong> two amounts.")
  + P(r"En un grup de teatre hi ha 14 xiques i 6 xics. La raó entre xiques i xics és:", r"En un grupo de teatro hay 14 chicas y 6 chicos. La razón entre chicas y chicos es:", r"A drama group has 14 girls and 6 boys. The ratio of girls to boys is:")
  + r'\[\frac{14}{6}=\frac{7}{3}\approx 2\dc33\]'
  + P(r"Vol dir que <strong>per cada 7 xiques hi ha 3 xics</strong>, o que hi ha unes \(2\dc33\) xiques per cada xic. La raó entre xics i xiques seria la inversa: \(\frac{6}{14}=\frac{3}{7}\).",
      r"Quiere decir que <strong>por cada 7 chicas hay 3 chicos</strong>, o que hay unas \(2\dc33\) chicas por cada chico. La razón entre chicos y chicas sería la inversa: \(\frac{6}{14}=\frac{3}{7}\).",
      r"It means <strong>for every 7 girls there are 3 boys</strong>, or about \(2\dc33\) girls per boy. The ratio of boys to girls would be the reciprocal: \(\frac{6}{14}=\frac{3}{7}\).")
  + note(r"Una raó s'escriu com una fracció, però no és ben bé el mateix: els seus termes poden ser decimals i normalment comparen <strong>dues quantitats diferents</strong> (no «parts d'un tot»). L'ordre importa: la raó xiques/xics no és la mateixa que xics/xiques.",
         r"Una razón se escribe como una fracción, pero no es exactamente lo mismo: sus términos pueden ser decimales y normalmente comparan <strong>dos cantidades distintas</strong> (no «partes de un todo»). El orden importa: la razón chicas/chicos no es la misma que chicos/chicas.",
         r"A ratio is written like a fraction, but it isn't quite the same thing: its terms can be decimals and it usually compares <strong>two different amounts</strong> (not “parts of a whole”). Order matters: girls/boys is not the same ratio as boys/girls."))
s1 += box('def', L('Proporció', 'Proporción', 'Proportion'),
  P(r"Una <strong>proporció</strong> és una igualtat entre dues raons. Es llig «\(a\) és a \(b\) com \(c\) és a \(d\)»:", r"Una <strong>proporción</strong> es una igualdad entre dos razones. Se lee «\(a\) es a \(b\) como \(c\) es a \(d\)»:", r"A <strong>proportion</strong> is an equality between two ratios, read “\(a\) is to \(b\) as \(c\) is to \(d\)”:")
  + r'\[\frac{a}{b}=\frac{c}{d}\qquad\text{p. ex.}\quad\frac{4}{6}=\frac{10}{15}\]'
  + P(r"\(a\) i \(d\) són els <strong>extrems</strong>; \(b\) i \(c\), els <strong>mitjans</strong>. Totes dues raons valen el mateix (\(0\dc\overline{6}\)): aquest valor comú s'anomena <strong>constant de proporcionalitat</strong>.",
      r"\(a\) y \(d\) son los <strong>extremos</strong>; \(b\) y \(c\), los <strong>medios</strong>. Las dos razones valen lo mismo (\(0\dc\overline{6}\)): este valor común se llama <strong>constante de proporcionalidad</strong>.",
      r"\(a\) and \(d\) are the <strong>extremes</strong>; \(b\) and \(c\), the <strong>means</strong>. Both ratios have the same value (\(0\dc\overline{6}\)): this common value is called the <strong>constant of proportionality</strong>."))
s1 += box('prop', L('Propietat fonamental de les proporcions', 'Propiedad fundamental de las proporciones', 'Key property of proportions'),
  P(r"En tota proporció, el <strong>producte dels extrems és igual al producte dels mitjans</strong>:", r"En toda proporción, el <strong>producto de los extremos es igual al producto de los medios</strong>:", r"In every proportion, the <strong>product of the extremes equals the product of the means</strong>:")
  + r'\[\frac{a}{b}=\frac{c}{d}\iff a\cdot d=b\cdot c\qquad\qquad \frac{4}{6}=\frac{10}{15}:\ \ 4\cdot15=60=6\cdot10\ ✓\]'
  + P(r"Ens serveix per a <strong>comprovar</strong> si dues raons formen proporció i per a calcular un terme desconegut, el <strong>quart proporcional</strong>: multipliquem els dos termes coneguts que estan «en creu» i dividim entre el que queda.",
      r"Nos sirve para <strong>comprobar</strong> si dos razones forman proporción y para calcular un término desconocido, el <strong>cuarto proporcional</strong>: multiplicamos los dos términos conocidos que están «en cruz» y dividimos entre el que queda.",
      r"We use it to <strong>check</strong> whether two ratios form a proportion and to find a missing term, the <strong>fourth proportional</strong>: multiply the two known terms that are “diagonal” to each other and divide by the one left.")
  + r'\[\frac{6}{x}=\frac{9}{12}\ \Rightarrow\ 9\cdot x=6\cdot12=72\ \Rightarrow\ x=\frac{72}{9}=\boxed{8}\]'
  + widget('w-prop', '⚖️', L('Calcula el terme desconegut', 'Calcula el término desconocido', 'Find the missing term'),
    '  <div class="wrow">' + frow(bare('a', '6'), '<i></i>', bare('b', 'x', 'text')) + '<span class="eqs">=</span>' + frow(bare('c', '9'), '<i></i>', bare('d', '12')) + '</div>\n'
    + '  ' + quick([('6;x;9;12', '6/x = 9/12'), ('x;15;8;20', 'x/15 = 8/20'), ('3,5;7;x;18', '3,5/7 = x/18'), ('12;16;9;x', '12/16 = 9/x'), ('4;6;10;15', '4/6 = 10/15 ?'), ('2,4;3;5;6', '2,4/3 = 5/6 ?')]) + '\n')
  + drill('prop', 'Entrena: calcula x', 'Entrena: calcula x', 'Train: find x'))
ck(Fr(72, 9), 8)
s1 += level(1, 1,
  prob(L(r"En una botiga hi ha 45 samarretes blanques i 27 de negres. a) Quina és la raó entre samarretes blanques i negres? Simplifica-la i explica què significa. b) I la raó entre les negres i el total?",
         r"En una tienda hay 45 camisetas blancas y 27 negras. a) ¿Cuál es la razón entre camisetas blancas y negras? Simplifícala y explica qué significa. b) ¿Y la razón entre las negras y el total?",
         r"A shop has 45 white T-shirts and 27 black ones. a) What is the ratio of white to black T-shirts? Simplify it and explain what it means. b) And the ratio of black ones to the total?"),
       r'\[\text{a) }\frac{45}{27}=\boxed{\frac{5}{3}}\qquad\text{b) }\frac{27}{45+27}=\frac{27}{72}=\boxed{\frac{3}{8}}\]',
       P(r"a) Per cada 5 samarretes blanques n'hi ha 3 de negres. b) 3 de cada 8 samarretes són negres.", r"a) Por cada 5 camisetas blancas hay 3 negras. b) 3 de cada 8 camisetas son negras.", r"a) For every 5 white T-shirts there are 3 black ones. b) 3 out of every 8 T-shirts are black.")))
ck(Fr(45, 27), Fr(5, 3)); ck(Fr(27, 72), Fr(3, 8))
s1 += level(2, 2,
  prob(L(r"a) Comprova si formen proporció: \(\frac{3\dc5}{5}\) i \(\frac{14}{20}\); \(\ \frac{8}{12}\) i \(\frac{6}{10}\). b) Calcula \(x\): \(\ \frac{x}{15}=\frac{8}{20}\ \) i \(\ \frac{12}{16}=\frac{9}{x}\).",
         r"a) Comprueba si forman proporción: \(\frac{3\dc5}{5}\) y \(\frac{14}{20}\); \(\ \frac{8}{12}\) y \(\frac{6}{10}\). b) Calcula \(x\): \(\ \frac{x}{15}=\frac{8}{20}\ \) y \(\ \frac{12}{16}=\frac{9}{x}\).",
         r"a) Check whether they form a proportion: \(\frac{3\dc5}{5}\) and \(\frac{14}{20}\); \(\ \frac{8}{12}\) and \(\frac{6}{10}\). b) Find \(x\): \(\ \frac{x}{15}=\frac{8}{20}\ \) and \(\ \frac{12}{16}=\frac{9}{x}\)."),
       r'\[3\dc5\cdot20=70=5\cdot14\ \Rightarrow\ \tri{Sí}{Sí}{Yes}\qquad 8\cdot10=80\neq12\cdot6=72\ \Rightarrow\ \text{No}\]',
       r'\[x=\frac{15\cdot8}{20}=\frac{120}{20}=\boxed{6}\qquad x=\frac{16\cdot9}{12}=\frac{144}{12}=\boxed{12}\]'))
ck(Dm('3.5') * 20, 70); ck(Fr(120, 20), 6); ck(Fr(144, 12), 12)
s1 += level(3, 3,
  prob(L(r"Per a pintar una paret de color taronja mesclem pintura roja i groga en la raó \(\frac{3}{5}\). Si tenim 2 L de pintura roja, quanta groga hi hem d'afegir? Quants litres de taronja tindrem?",
         r"Para pintar una pared de color naranja mezclamos pintura roja y amarilla en la razón \(\frac{3}{5}\). Si tenemos 2 L de pintura roja, ¿cuánta amarilla tenemos que añadir? ¿Cuántos litros de naranja tendremos?",
         r"To paint a wall orange we mix red and yellow paint in the ratio \(\frac{3}{5}\). If we have 2 L of red paint, how much yellow do we need to add? How many litres of orange will we get?"),
       P(r"La raó roja/groga s'ha de mantindre: plantegem una proporció.", r"La razón roja/amarilla se tiene que mantener: planteamos una proporción.", r"The red/yellow ratio must stay the same: set up a proportion."),
       r'\[\frac{3}{5}=\frac{2}{x}\ \Rightarrow\ 3x=10\ \Rightarrow\ x=\frac{10}{3}\approx\boxed{3\dc33\ \text{L}}\ \tri{de groga}{de amarilla}{of yellow}\]',
       P(r"En total: \(2+\frac{10}{3}=\frac{16}{3}\approx 5\dc33\) L de pintura taronja.", r"En total: \(2+\frac{10}{3}=\frac{16}{3}\approx 5\dc33\) L de pintura naranja.", r"In total: \(2+\frac{10}{3}=\frac{16}{3}\approx 5\dc33\) L of orange paint.")))
ck(2 + Fr(10, 3), Fr(16, 3))
s1 += practice([
  ('★', L(r"a) En un aparcament hi ha 36 cotxes i 12 motos. Calcula la raó cotxes/motos i interpreta-la. b) Formen proporció \(\frac{6}{9}\) i \(\frac{14}{21}\)?", r"a) En un aparcamiento hay 36 coches y 12 motos. Calcula la razón coches/motos e interprétala. b) ¿Forman proporción \(\frac{6}{9}\) y \(\frac{14}{21}\)?", r"a) A car park has 36 cars and 12 motorbikes. Find the cars/motorbikes ratio and interpret it. b) Do \(\frac{6}{9}\) and \(\frac{14}{21}\) form a proportion?")),
  ('★★', L(r"c) Calcula \(x\): \(\frac{3\dc5}{7}=\frac{x}{18}\). d) Calcula \(x\): \(\frac{5}{x}=\frac{2}{0\dc8}\).", r"c) Calcula \(x\): \(\frac{3\dc5}{7}=\frac{x}{18}\). d) Calcula \(x\): \(\frac{5}{x}=\frac{2}{0\dc8}\).", r"c) Find \(x\): \(\frac{3\dc5}{7}=\frac{x}{18}\). d) Find \(x\): \(\frac{5}{x}=\frac{2}{0\dc8}\).")),
  ('★★★', L(r"e) Les edats d'un pare i del seu fill estan en la raó \(\frac{9}{4}\). Si el pare té 45 anys, quants en té el fill? Quina diferència d'edat hi ha?", r"e) Las edades de un padre y de su hijo están en la razón \(\frac{9}{4}\). Si el padre tiene 45 años, ¿cuántos tiene el hijo? ¿Qué diferencia de edad hay?", r"e) A father's and his son's ages are in the ratio \(\frac{9}{4}\). If the father is 45, how old is the son? What is the age difference?"))],
  P(r"a) \(\frac{36}{12}=3\): hi ha 3 cotxes per cada moto. &nbsp; b) Sí: \(6\cdot21=126=9\cdot14\).", r"a) \(\frac{36}{12}=3\): hay 3 coches por cada moto. &nbsp; b) Sí: \(6\cdot21=126=9\cdot14\).", r"a) \(\frac{36}{12}=3\): there are 3 cars for every motorbike. &nbsp; b) Yes: \(6\cdot21=126=9\cdot14\).")
  + P(r"c) \(x=\frac{3\dc5\cdot18}{7}=9\). &nbsp; d) \(x=\frac{5\cdot0\dc8}{2}=2\). &nbsp; e) \(\frac{45}{x}=\frac{9}{4}\Rightarrow x=\frac{45\cdot4}{9}=20\) anys; diferència: 25 anys.", r"c) \(x=\frac{3\dc5\cdot18}{7}=9\). &nbsp; d) \(x=\frac{5\cdot0\dc8}{2}=2\). &nbsp; e) \(\frac{45}{x}=\frac{9}{4}\Rightarrow x=\frac{45\cdot4}{9}=20\) años; diferencia: 25 años.", r"c) \(x=\frac{3\dc5\cdot18}{7}=9\). &nbsp; d) \(x=\frac{5\cdot0\dc8}{2}=2\). &nbsp; e) \(\frac{45}{x}=\frac{9}{4}\Rightarrow x=\frac{45\cdot4}{9}=20\) years; difference: 25 years."))
ck(6 * 21, 126); ck(9 * 14, 126); ck(Dm('3.5') * 18 / 7, 9); ck(5 * Dm('0.8') / 2, 2); ck(Fr(45 * 4, 9), 20)

# ============================================================ 6.2
s2 = box('def', L('Magnituds directament proporcionals', 'Magnitudes directamente proporcionales', 'Directly proportional quantities'),
  P(r"Una <strong>magnitud</strong> és tot allò que es pot mesurar: la massa, el preu, el temps, la distància… Dues magnituds són <strong>directament proporcionals</strong> si, quan una es multiplica (o es divideix) per un nombre, l'altra queda multiplicada (o dividida) pel <strong>mateix</strong> nombre: el doble → el doble, la meitat → la meitat.",
    r"Una <strong>magnitud</strong> es todo aquello que se puede medir: la masa, el precio, el tiempo, la distancia… Dos magnitudes son <strong>directamente proporcionales</strong> si, cuando una se multiplica (o se divide) por un número, la otra queda multiplicada (o dividida) por el <strong>mismo</strong> número: el doble → el doble, la mitad → la mitad.",
    r"A <strong>quantity</strong> (magnitude) is anything we can measure: mass, price, time, distance… Two quantities are <strong>directly proportional</strong> if, when one is multiplied (or divided) by a number, the other is multiplied (or divided) by the <strong>same</strong> number: double → double, half → half.")
  + P(r"Exemple: un cotxe va a velocitat constant i recorre 90 km cada hora.", r"Ejemplo: un coche va a velocidad constante y recorre 90 km cada hora.", r"Example: a car travels at a constant speed and covers 90 km every hour.")
  + table([L('Temps (h)', 'Tiempo (h)', 'Time (h)'), '1', '2', '3', r'\(4\dc5\)', '6'], [[L('Distància (km)', 'Distancia (km)', 'Distance (km)'), '90', '180', '270', '405', '540']], 'data ptab')
  + P(r"Els quocients entre les quantitats corresponents són tots iguals: \(\frac{180}{2}=\frac{270}{3}=\frac{405}{4\dc5}=90\). Aquest nombre és la <strong>constant de proporcionalitat directa</strong>, \(k\) (aquí, els km que fa en una hora). Qualsevol parella de columnes forma una proporció.",
      r"Los cocientes entre las cantidades correspondientes son todos iguales: \(\frac{180}{2}=\frac{270}{3}=\frac{405}{4\dc5}=90\). Este número es la <strong>constante de proporcionalidad directa</strong>, \(k\) (aquí, los km que hace en una hora). Cualquier pareja de columnas forma una proporción.",
      r"The quotients of corresponding values are all equal: \(\frac{180}{2}=\frac{270}{3}=\frac{405}{4\dc5}=90\). This number is the <strong>constant of direct proportionality</strong>, \(k\) (here, the km covered in one hour). Any pair of columns forms a proportion.")
  + r'\[\frac{\tri{2a magnitud}{2.ª magnitud}{2nd quantity}}{\tri{1a magnitud}{1.ª magnitud}{1st quantity}}=k\qquad\Longleftrightarrow\qquad \tri{2a}{2.ª}{2nd}=k\cdot\tri{1a}{1.ª}{1st}\]'
  + figs((svg_points([(1, 90), (2, 180), (3, 270), (4.5, 405)], 6, 560, 'h', 'km', line=90), L("Els punts estan sobre una recta que passa per l'origen", 'Los puntos están sobre una recta que pasa por el origen', 'The points lie on a straight line through the origin')))
  + note(r"<strong>Compte!</strong> No n'hi ha prou que «si una augmenta, l'altra també». L'edat i el pes d'una persona augmenten juntes, però no en la mateixa proporció. I una factura de la llum amb una quota fixa tampoc no és proporcional als kWh consumits: el doble de consum no costa el doble.",
         r"<strong>¡Cuidado!</strong> No basta con que «si una aumenta, la otra también». La edad y el peso de una persona aumentan juntos, pero no en la misma proporción. Y una factura de la luz con una cuota fija tampoco es proporcional a los kWh consumidos: el doble de consumo no cuesta el doble.",
         r"<strong>Careful!</strong> It isn't enough that “when one goes up, so does the other”. A person's age and weight both increase, but not in the same proportion. And an electricity bill with a fixed charge isn't proportional to the kWh used either: twice the usage doesn't cost twice as much.", '⚠️'))
ck(Dm(405) / Dm('4.5'), 90)
s2 += box('prop', L('Tres maneres de resoldre problemes de proporcionalitat directa', 'Tres maneras de resolver problemas de proporcionalidad directa', 'Three ways to solve direct proportion problems'),
  P(r"<strong>Problema:</strong> 5 kg de taronges costen \(7\dc50\) €. Quant costen 8 kg?", r"<strong>Problema:</strong> 5 kg de naranjas cuestan \(7\dc50\) €. ¿Cuánto cuestan 8 kg?", r"<strong>Problem:</strong> 5 kg of oranges cost \(7\dc50\) €. How much do 8 kg cost?")
  + P(r"<strong>1. Reducció a la unitat.</strong> Calculem primer quant val <strong>una</strong> unitat (dividint) i després multipliquem:", r"<strong>1. Reducción a la unidad.</strong> Calculamos primero cuánto vale <strong>una</strong> unidad (dividiendo) y después multiplicamos:", r"<strong>1. Unit method.</strong> First find the value of <strong>one</strong> unit (by dividing), then multiply:")
  + r'\[1\ \text{kg}:\ \ 7\dc50:5=1\dc50\ €\qquad\qquad 8\ \text{kg}:\ \ 1\dc50\cdot8=\boxed{12\ €}\]'
  + P(r"<strong>2. Taula de proporcionalitat.</strong> Posem les dades en una taula. La constant és \(k=\frac{7\dc50}{5}=1\dc50\); cada valor de baix és el de dalt multiplicat per \(k\):", r"<strong>2. Tabla de proporcionalidad.</strong> Ponemos los datos en una tabla. La constante es \(k=\frac{7\dc50}{5}=1\dc50\); cada valor de abajo es el de arriba multiplicado por \(k\):", r"<strong>2. Proportion table.</strong> Put the data in a table. The constant is \(k=\frac{7\dc50}{5}=1\dc50\); each bottom value is the top one times \(k\):")
  + table([L('Massa (kg)', 'Masa (kg)', 'Mass (kg)'), '5', '1', '8'], [[L('Preu (€)', 'Precio (€)', 'Price (€)'), r'\(7\dc50\)', r'\(1\dc50\)', r'\(\boxed{12}\)']], 'data ptab')
  + P(r"<strong>3. Regla de tres directa.</strong> Escrivim les dades en dues files, cada magnitud en una columna. Com que són directament proporcionals, formen una proporció i calculem el quart proporcional:", r"<strong>3. Regla de tres directa.</strong> Escribimos los datos en dos filas, cada magnitud en una columna. Como son directamente proporcionales, forman una proporción y calculamos el cuarto proporcional:", r"<strong>3. Direct rule of three.</strong> Write the data in two rows, one quantity per column. Since they're directly proportional, they form a proportion and we find the fourth proportional:")
  + r3('5', 'kg', r'7\dc50', '€', '8', 'kg')
  + r'\[\frac{5}{8}=\frac{7\dc50}{x}\ \Rightarrow\ x=\frac{7\dc50\cdot8}{5}=\frac{60}{5}=\boxed{12\ €}\]'
  + note(r"Truc per a recordar-ho: en la regla de tres <strong>directa</strong> multipliquem <strong>en creu</strong> (\(7\dc50\cdot8\)) i dividim entre el nombre que queda (5). Abans, pregunta't sempre: <em>si una magnitud augmenta, l'altra augmenta en la mateixa proporció?</em>",
         r"Truco para recordarlo: en la regla de tres <strong>directa</strong> multiplicamos <strong>en cruz</strong> (\(7\dc50\cdot8\)) y dividimos entre el número que queda (5). Antes, pregúntate siempre: <em>si una magnitud aumenta, ¿la otra aumenta en la misma proporción?</em>",
         r"Memory trick: in the <strong>direct</strong> rule of three, multiply <strong>across</strong> (\(7\dc50\cdot8\)) and divide by the remaining number (5). Before that, always ask: <em>if one quantity goes up, does the other go up in the same proportion?</em>"))
ck(Dm('7.50') / 5 * 8, 12); ck(Dm('7.50') * 8, 60)
s2 += widget('w-r3', '📐', L('Regla de tres simple', 'Regla de tres simple', 'Simple rule of three'),
  f'  <div class="wrow">{gseg("t", [("d", L("Directa", "Directa", "Direct")), ("i", L("Inversa", "Inversa", "Inverse"))], "d")}</div>\n'
  + '  <div class="r3in">'
  + nin('a', '', '', '', '5', 's') + nin('ma', '', '', '', 'kg', 'u', 'text') + '<span class="arr">→</span>' + nin('b', '', '', '', '7,50', 's') + nin('mb', '', '', '', '€', 'u', 'text')
  + nin('c', '', '', '', '8', 's') + '<span class="u0"></span><span class="arr">→</span><span class="xq">x</span><span></span></div>\n'
  + '  ' + quick([('d;5;kg;7,50;€;8', '5 kg → 7,50 €'), ('d;3;h;270;km;4,5', '3 h → 270 km'), ('d;12;L;9;€;20', '12 L → 9 €'), ('d;250;g;3,40;€;750', '250 g → 3,40 €'), ('i;6;' + 'obrers;10;dies;4', '6 obrers → 10 dies'), ('i;80;km/h;3;h;120', '80 km/h → 3 h')]) + '\n')
s2 += drill('r3d', 'Entrena: proporcionalitat directa', 'Entrena: proporcionalidad directa', 'Train: direct proportion')
s2 += level(1, 1,
  prob(L(r"Completa la taula de proporcionalitat directa i calcula'n la constant:", r"Completa la tabla de proporcionalidad directa y calcula su constante:", r"Complete the direct proportion table and find its constant:")
       + table([L('Quaderns', 'Cuadernos', 'Notebooks'), '1', '3', '5', '?', '12'], [[L('Preu (€)', 'Precio (€)', 'Price (€)'), '?', r'\(4\dc20\)', '?', r'\(11\dc20\)', '?']], 'data ptab'),
       P(r"Constant: \(k=4\dc20:3=1\dc40\) € per quadern. Per a anar de dalt a baix multipliquem per \(k\); de baix a dalt, dividim:", r"Constante: \(k=4\dc20:3=1\dc40\) € por cuaderno. Para ir de arriba abajo multiplicamos por \(k\); de abajo arriba, dividimos:", r"Constant: \(k=4\dc20:3=1\dc40\) € per notebook. To go from top to bottom multiply by \(k\); from bottom to top, divide:"),
       table([L('Quaderns', 'Cuadernos', 'Notebooks'), '1', '3', '5', r'\(\boxed{8}\)', '12'], [[L('Preu (€)', 'Precio (€)', 'Price (€)'), r'\(\boxed{1\dc40}\)', r'\(4\dc20\)', r'\(\boxed{7}\)', r'\(11\dc20\)', r'\(\boxed{16\dc80}\)']], 'data ptab')))
